import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { requireAuth, getTenantScope } from "@/lib/auth-guard";
import { chatWithFallback, type LLMMessage } from "@/lib/llm";

export const dynamic = "force-dynamic";

interface SeriesBody {
  /** Base caption / template. Each occurrence's variant content is
   *  generated by AI so it varies slightly while staying on-message. */
  caption: string;
  /** Optional post title prefix. Defaults to "Series". */
  title?: string;
  /** Platform id, e.g. "instagram" — must resolve to one of the caller's
   *  connected accounts. */
  platform: string;
  /** daily | weekly — how often a new occurrence should be scheduled. */
  frequency: "daily" | "weekly";
  /** Duration in weeks — must be 4, 8, or 12. */
  duration: 4 | 8 | 12;
  /** ISO timestamp for the FIRST occurrence. Subsequent occurrences are
   *  auto-computed from `frequency`. */
  startDate: string;
}

/**
 * POST /api/posts/series
 *
 * Creates a content series — `duration` weeks of recurring posts, each
 * scheduled at the same hour-of-day, spaced by `frequency` (daily or
 * weekly). Each occurrence's caption is AI-generated to be a slightly
 * distinct variant of the base `caption` so the series doesn't feel
 * repetitive.
 *
 * Returns:
 *   { ok: true, created: 8, postIds: [...] }
 */
export async function POST(req: NextRequest) {
  const { user, error } = await requireAuth(req);
  if (error) return error;

  const scope = getTenantScope(user!);
  const postCustomerId = scope.isSuperAdmin ? null : scope.customerId;

  const body = (await req.json()) as SeriesBody;
  if (!body?.caption || !body?.platform || !body?.startDate) {
    return NextResponse.json({ error: "caption, platform, startDate required" }, { status: 400 });
  }
  if (!["daily", "weekly"].includes(body.frequency)) {
    return NextResponse.json({ error: "frequency must be 'daily' or 'weekly'" }, { status: 400 });
  }
  if (![4, 8, 12].includes(body.duration)) {
    return NextResponse.json({ error: "duration must be 4, 8, or 12 weeks" }, { status: 400 });
  }

  // Resolve platform → account (first matching connected account).
  const account = await db.account.findFirst({
    where: {
      platform: body.platform,
      ...(scope.isSuperAdmin ? {} : { customerId: scope.customerId }),
    },
    select: { id: true, handle: true },
  });
  if (!account) {
    return NextResponse.json(
      { error: `No connected ${body.platform} account in your tenant` },
      { status: 404 }
    );
  }

  const start = new Date(body.startDate);
  if (Number.isNaN(start.getTime())) {
    return NextResponse.json({ error: "Invalid startDate" }, { status: 400 });
  }

  // Compute occurrence dates.
  const stepDays = body.frequency === "daily" ? 1 : 7;
  const totalOccurrences = body.duration * (body.frequency === "daily" ? 7 : 1);
  const occurrences: Date[] = [];
  for (let i = 0; i < totalOccurrences; i++) {
    const d = new Date(start.getTime() + i * stepDays * 86400000);
    occurrences.push(d);
  }

  // Cap at 60 occurrences to keep things sane (12 weeks × daily = 84; we
  // floor at 60 to avoid runaway AI generation costs).
  const cappedOccurrences = occurrences.slice(0, 60);

  // AI-generate one variant per occurrence. We batch the request — ask
  // the model for N distinct rewrites at once — to keep the round-trip
  // count low.
  let variants: string[] = [];
  try {
    const llmMessages: LLMMessage[] = [
      {
        role: "system",
        content:
          "You are a social media copywriter. Generate distinct variations of a base caption for a recurring content series. Each variation must be genuinely distinct in wording while preserving the core message. Respond with ONLY a JSON array of strings — no markdown, no prose.",
      },
      {
        role: "user",
        content: `Base caption:
"""
${body.caption}
"""

Generate exactly ${cappedOccurrences.length} distinct variations for a ${body.frequency} recurring series over ${body.duration} weeks. Each variation should feel fresh (different hook, angle, or wording) but stay on-message. Do NOT prepend "1." or labels.

Respond with ONLY a JSON array, e.g. ["variant 1", "variant 2", ...].`,
      },
    ];
    const result = await chatWithFallback(llmMessages);
    const cleaned = result.content
      .replace(/```json/gi, "")
      .replace(/```/g, "")
      .trim();
    const startBrace = cleaned.indexOf("[");
    const endBrace = cleaned.lastIndexOf("]");
    if (startBrace >= 0 && endBrace > startBrace) {
      const parsed = JSON.parse(cleaned.slice(startBrace, endBrace + 1));
      if (Array.isArray(parsed)) {
        variants = parsed.filter((v) => typeof v === "string").slice(0, cappedOccurrences.length);
      }
    }
  } catch (e) {
    console.error("[series] AI generation failed:", e instanceof Error ? e.message : String(e));
    // Continue with fallback variants below.
  }

  // Fill missing variants with the base caption (so the series still
  // creates even if AI fails).
  while (variants.length < cappedOccurrences.length) {
    variants.push(body.caption);
  }

  const titlePrefix = (body.title ?? "Series").trim() || "Series";
  const postIds: string[] = [];

  for (let i = 0; i < cappedOccurrences.length; i++) {
    const date = cappedOccurrences[i];
    const content = variants[i] ?? body.caption;
    const post = await db.post.create({
      data: {
        title: `${titlePrefix} — ${i + 1}/${cappedOccurrences.length}`,
        caption: body.caption, // keep the base template as the post caption
        mediaType: "image",
        tone: "professional",
        status: "scheduled",
        scheduledAt: date,
        authorId: user!.userId,
        customerId: postCustomerId,
        variants: {
          create: {
            accountId: account.id,
            content,
            hashtags: null,
            status: "scheduled",
            publishedAt: null,
          },
        },
      },
    });
    postIds.push(post.id);
  }

  try {
    await db.activity.create({
      data: {
        userId: user!.userId,
        type: "post_scheduled",
        description: `created ${postIds.length}-post ${body.frequency} series "${titlePrefix}"`,
      },
    });
  } catch {
    /* ignore */
  }

  return NextResponse.json({
    ok: true,
    created: postIds.length,
    postIds,
    occurrences: cappedOccurrences.map((d) => d.toISOString()),
  });
}
